def makeEqual(words):
    # Step 1: Build frequency map for all letters (26 letters a-z)
    freq = [0] * 26
    for word in words:
        for ch in word:
            freq[ord(ch) - ord('a')] += 1

    n = len(words)

    # Step 2: For every character, check if count is divisible by n
    for count in freq:
        if count % n != 0:
            return False
    return True
